'use strict';
const Dashboard={filters:{},snapshot:null,sequence:0,
async init(){if(!Business.can('dashboard:read'))return;const section=document.createElement('section');section.id='dashboard';section.className='dashboard';section.innerHTML='<div class="page-heading"><div><h1>信息总览</h1><p>按入库、在库、出库流程查看当前授权范围。</p></div><a class="button secondary" href="/inventory">进入库存查询</a></div><details class="panel overview-filter-box"><summary>统计期间与数据范围</summary><div id="dashboard-filters"></div></details><p id="dashboard-error" class="error" role="alert"></p><div id="dashboard-content"></div>';document.querySelector('#inventory').before(section);const m=await Business.load(),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lubumbashi',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),from=today.slice(0,8)+'01';const select=(label,key,rows,name)=>`<label>${label}<select name="${key}">${Business.options(rows,null,name,true)}</select></label>`;
 $('dashboard-filters').innerHTML=`<form id="dashboard-form" class="filters"><div class="form-grid">${Flow.field('统计开始日期','from','date',from,'required')}${Flow.field('统计截止日期','to','date',today,'required')}${select('货权客户','customer_id',m.customers,'name')}${select('仓库','warehouse_id',m.warehouses,'name')}${select('货位','location_id',m.locations,'code')}${select('生产批次','batch_id',m.batches,'code')}</div><button class="button primary">刷新信息总览</button></form>`;this.filters={from,to:today};$('dashboard-form').onsubmit=async e=>{e.preventDefault();this.filters=Object.fromEntries(new FormData(e.target));e.submitter.disabled=true;try{await this.refresh();}finally{e.submitter.disabled=false;}};await this.refresh();let timer;window.addEventListener('inventory-changed',()=>{clearTimeout(timer);timer=setTimeout(()=>this.refresh(),300);});window.addEventListener('session-expired',()=>{$('dashboard-content').replaceChildren();this.snapshot=null;});},
card(label,value,unit,extra=''){return `<article class="overview-value ${extra}"><span>${label}</span><strong>${esc(value)}<small>${unit}</small></strong></article>`;},
link(label,n,unit,path,permission){const text=`<span>${label}</span><strong>${esc(n||0)}<small>${unit}</small></strong>`;return path&&Business.can(permission)?`<a class="overview-state" href="${path}&${new URLSearchParams({...this.filters,as_of:this.snapshot?.window.end||''})}">${text}<span aria-hidden="true">→</span></a>`:`<div class="overview-state">${text}</div>`;},
async refresh(){const seq=++this.sequence;try{const q=new URLSearchParams(Object.entries(this.filters).filter(([,v])=>v)),[r,legacy]=await Promise.all([API.request('/dashboard/workflow?'+q),API.request('/dashboard?'+q)]);if(seq!==this.sequence||!window.AppSignedIn)return;this.snapshot={...legacy,workflow:r};$('dashboard-error').textContent='';const p=r.period,c=r.current,s=r.states,card=this.card.bind(this),link=this.link.bind(this),fmt=Tonnes.format;
 $('dashboard-content').innerHTML=`<p class="overview-scope"><span>统计期间</span> <strong data-no-i18n>${esc(r.window.from)} — ${esc(r.window.to)}</strong> · <span>现场与业务状态截至</span> <time data-no-i18n>${esc(new Date(r.window.end).toISOString().replace('T',' ').slice(0,19))} UTC</time></p>${r.history_partial?'<p class="dialog-notice">期间早于可追溯历史起点，仅展示可验证区间；不推算缺失历史。</p>':''}<div class="overview-core"><section class="panel overview-module" data-overview-module="inbound"><h2><span aria-hidden="true">↙</span> 入库</h2>${card('本期已审核入库',p.inbound_bundles,'捆')}${r.pending_receipts!==null?card('当前待审核入库单',r.pending_receipts,'单',r.pending_receipts?'attention':''):''}<p>按审核通过并完成入库记账时间统计，待审核及驳回单不计入。</p></section><section class="panel overview-module" data-overview-module="onhand"><h2><span aria-hidden="true">▦</span> 在库</h2>${card('当前现场库存',c.onsite_bundles,'捆')}${card('现场已知净重合计',fmt(c.known_net_weight),'t')}${card('未完成检斤',c.unweighed_bundles,'捆',c.unweighed_bundles?'attention':'')}${card('当前可备货',c.available_bundles,'捆')}${card('备货作业中或已备货',c.preparing_bundles,'捆')}<p>包含已装车待离场，排除已离场待审批。未知重量不按零计入。</p></section><section class="panel overview-module" data-overview-module="outbound"><h2><span aria-hidden="true">↗</span> 出库</h2>${card('本期正式出库',p.outbound_bundles,'捆')}${card('本期正式出库净重',fmt(p.outbound_weight===null&&p.outbound_bundles===0?'0':p.outbound_weight),'t')}${card('已离场待正式出库审批',c.departed_pending_bundles,'捆',c.departed_pending_bundles?'attention':'')}<p>仅最终审批并完成出库记账计入本期出库，车辆离场不提前记账。</p></section></div><section class="overview-workflow"><h2>捆包业务状态</h2><p>当前状态按捆唯一分类；待审核入库使用单据数，已出库另列历史范围。</p><div class="overview-stages"><section class="panel"><h3>入库阶段</h3>${r.pending_receipts!==null?link('待审批入库单',r.pending_receipts,'单','/receipts?status=PENDING','receipt:review'):''}${link('已入库、可备货',s.available,'捆','/inventory?workflow=available','inventory:read')}</section><section class="panel"><h3>备货阶段</h3>${link('备货作业中',s.working,'捆','/preparation?workflow=working','allocation:read')}${link('备货待审核',s.preparation_pending,'捆','/preparation?workflow=preparation_pending','allocation:read')}${link('已备货待装车',s.prepared,'捆','/preparation?workflow=prepared','allocation:read')}${s.adjustment_pending?link('库存调整待核查',s.adjustment_pending,'捆','/inventory?workflow=adjustment_pending','inventory:read'):''}${s.sampling_unallocated?link('未分配取样中',s.sampling_unallocated,'捆','/inventory?workflow=sampling_unallocated','inventory:read'):''}${s.other_locked?link('其他有效锁定',s.other_locked,'捆','/inventory?workflow=other_locked','inventory:read'):''}</section><section class="panel"><h3>装车及出库阶段</h3>${link('装车待审核',s.loading_pending,'捆','/outbounds?workflow=loading_pending','load:read')}${link('已审核待离场',s.ready_departure,'捆','/outbounds?workflow=ready_departure','load:read')}${link('已离场待出库审批',s.departed_pending,'捆','/outbounds?workflow=departed_pending','load:read')}${link('已离场待纠正',s.departed_correction,'捆','/outbounds?workflow=departed_correction','load:read')}${s.legacy_loaded?link('历史装车待核查',s.legacy_loaded,'捆','/inventory?workflow=legacy_loaded','inventory:read'):''}</section></div></section><details class="panel overview-other"><summary>账面口径、历史状态与趋势</summary><div class="overview-ledger">${card('截至时点账面库存',c.ledger_bundles,'捆')}${card('历史累计已出库',s.outbound_history||0,'捆')}${s.other_history?card('其他历史状态',s.other_history,'捆'):''}</div><p>本期入库和本期出库是期间发生量，现场库存是时点存量，不直接加减。历史重量不完整时仅显示已知合计。</p><p>下列为既有正式库存账趋势，包含已离场待审批差异；不作为现场实物重量。</p>${Control.reportTable(legacy.trend.map(x=>({period:x.period,opening_weight:x.opening_weight,inbound_weight:x.inbound_weight,outbound_weight:x.outbound_weight,closing_weight:x.closing_weight})))}</details>`;
 }catch(e){if(seq!==this.sequence)return;$('dashboard-error').textContent=e.message;$('dashboard-content').replaceChildren();this.snapshot=null;}},async details(metric){if(!this.snapshot)throw Error('请先刷新信息总览');const q=new URLSearchParams({...this.filters,metric,as_of:this.snapshot.window.end}),r=await API.request('/dashboard/details?'+q);Business.open(r.title,Control.reportTable(r.rows));}};
Dashboard.ready=Dashboard.init().catch(e=>notify(e.message));
const OverviewDrill={async render(){const q=new URLSearchParams(location.search),state=q.get('workflow'),r=await API.request('/dashboard/workflow?'+new URLSearchParams({...Object.fromEntries(q),state}));const title=Router.names[location.pathname.slice(1)]||'业务详情';Router.page(title+' · 状态筛选',`<p>来自信息总览的授权状态明细，按同一截止时点和数据范围统计。</p><p>${r.items.length} <span>捆</span></p><a class="button secondary" href="${location.pathname}">清除状态筛选</a><div class="account-table-scroll"><table><thead><tr>${['捆包编号','Lot No.','货位','库存状态','净重（吨）'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${r.items.map(s=>`<tr><td>${Business.can('inventory:read')?`<a href="/inventory/${encodeURIComponent(s.bundle_no)}" data-no-i18n>${esc(s.bundle_no)}</a>`:`<span data-no-i18n>${esc(s.bundle_no)}</span>`}</td><td data-no-i18n>${esc(s.lot_no||'—')}</td><td data-no-i18n>${esc(s.location||'—')}</td><td>${esc(s.business_status||s.physical_status)}</td><td>${Tonnes.format(s.weight)}</td></tr>`).join('')}</tbody></table></div>`);}};
